create or replace function public.get_owner_open_rescue_cases() returns jsonb language plpgsql security definer set search_path=public set row_security=off as $$ begin if public.current_role()<>'platform_admin' then raise exception 'PLATFORM_ADMIN_REQUIRED'; end if; return coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'job_id',r.job_id,'status',r.status,'severity',r.severity,'reason',r.reason,'recommended_agency_id',r.recommended_agency_id,'offered_agency_id',r.offered_agency_id,'offered_agency_name',oa.name,'offered_at',r.offered_at,'accepted_agency_id',r.accepted_agency_id,'accepted_agency_name',aa.name,'accepted_at',r.accepted_at,'opened_at',r.opened_at) order by r.opened_at desc) from public.mission_rescue_cases r left join public.agencies oa on oa.id=r.offered_agency_id left join public.agencies aa on aa.id=r.accepted_agency_id where r.status='open'),'[]'::jsonb); end $$;
revoke all on function public.get_owner_open_rescue_cases() from public,anon;
grant execute on function public.get_owner_open_rescue_cases() to authenticated;
